    else -> "large"
}

package corpus.binarywhen

fun label(present: Boolean): String = when (present) {
    true -> "present"
    false -> "empty"
}

package corpus.binarywhen

fun label(read: () -> Int): String = when (val code = read()) {
    0 -> "empty"
    else -> "present-$code"
}

